        if spec.body != nil {
            headers["Content-Type"] = spec.contentType ?? "application/json"
        }
        for (name, value) in spec.headers { headers[name] = value }
        for (name, value) in options.headers { headers[name] = value }
        if let idempotencyKey {
            headers["Idempotency-Key"] = idempotencyKey
        }
        switch spec.auth {
        case .key:
            guard let apiKey else {
                throw ConfigurationError(message: "No API key: pass apiKey to TungoClient or set the TUNGO_API_KEY environment variable.")
            }
            headers["x-api-key"] = apiKey.value
            headers["Authorization"] = nil
        case .none:
            // Public endpoints and incoming hooks must not receive credentials.
            headers["x-api-key"] = nil
            headers["Authorization"] = nil
