                throw ValidationError(message: "The header '\(name.isEmpty ? "(empty)" : name)' has an invalid name or value.")
            }
        }
        return TungoHTTPRequest(method: spec.method, url: url, headers: headers.dictionary, body: spec.body, idleTimeout: idleTimeout)
    }

