    /// Runs an operation with a total time limit. The limit and the caller's cancellation both stop it.
    static func withDeadline<T: Sendable>(_ seconds: TimeInterval, _ operation: @escaping @Sendable () async throws -> T) async throws -> T {
        guard seconds.isFinite else { return try await operation() }
        return try await withThrowingTaskGroup(of: T?.self) { group in
            group.addTask { try await operation() }
            group.addTask {
                try await ClientCore.realSleep(seconds)
                return nil
            }
            defer { group.cancelAll() }
            guard let first = try await group.next() else { throw CancellationError() }
            if let value = first { return value }
            throw TimeoutError(kind: .request, timeout: seconds)
        }
    }

    static func describe(_ error: Error) -> String {
        guard let decoding = error as? DecodingError else { return error.localizedDescription }
        func path(_ context: DecodingError.Context) -> String {
            var joined = ""
            for key in context.codingPath {
                if let index = key.intValue {
                    joined += "[\(index)]"
                } else {
                    joined += (joined.isEmpty ? "" : ".") + key.stringValue
                }
            }
            return joined.isEmpty ? "the top level" : joined
        }
        switch decoding {
        case .keyNotFound(let key, let context): return "the required field '\(key.stringValue)' is missing at \(path(context))"
        case .typeMismatch(_, let context): return "unexpected type at \(path(context)): \(context.debugDescription)"
        case .valueNotFound(_, let context): return "unexpected null at \(path(context))"
        case .dataCorrupted(let context): return "invalid data at \(path(context)): \(context.debugDescription)"
        @unknown default: return error.localizedDescription
        }
    }
